let { defaultRoots, noSelectionRoots } = target;

if (!defaultRoots || !noSelectionRoots) {
	/* eslint-disable camelcase */
	const checkForRoot = ({ type, additional_data = {} }) => {
		/* eslint-disable camelcase */
		const { actionType, reportType, type: addType } = additional_data;
		return (
			actionType === 'itemtype' ||
			type === 'separator' ||
			(addType === 'report' && reportType === 'itemtype')
		);
	};
	// Reports should be on the menu's toplevel in
	// case when no items in the grid are selected
	defaultRoots = control.roots;
	const data = control.data;
	noSelectionRoots = defaultRoots.reduce((roots, itemId) => {
		const item = data.get(itemId);
		checkForRoot(item) && roots.push(itemId);

		item.children?.forEach(
			(itemId) => checkForRoot(data.get(itemId)) && roots.push(itemId)
		);

		return roots;
	}, []);
}

const { grid } = options.getState();
control.roots = grid.selectedRows.length ? defaultRoots : noSelectionRoots;

return { defaultRoots, noSelectionRoots };
